mapper.select:
SELECT P.PRODUCT_ID, P.MEMBER_ID, P.UNIV_ID, P.PRODUCT_NAME, P.PRICE, P.VIEW_COUNT, P.IS_DELETED, P.CREATED_AT, P.UPDATED_AT, P.PRODUCT_STATUS, P.PLACE, P.CATEGORY, M.MEMBER_NAME AS SELLER_NAME, MD.COMMUNITY_NICKNAME AS SELLER_NICKNAME, (SELECT COUNT(*) FROM PRODUCT_LIKE PL WHERE PL.PRODUCT_ID = P.PRODUCT_ID) AS LIKE_COUNT, (SELECT COUNT(*) FROM TRADE_CHAT_ROOM TC WHERE TC.PRODUCT_ID = P.PRODUCT_ID) AS CHAT_COUNT, (SELECT COUNT(*) FROM PRODUCT_REPORT PR WHERE PR.PRODUCT_ID = P.PRODUCT_ID) AS REPORT_COUNT, 0 AS HAS_UNREAD_TRADE_CHAT, CASE WHEN (SELECT COUNT(*) FROM PRODUCT_REPORT PR WHERE PR.PRODUCT_ID = P.PRODUCT_ID) >= 5 THEN 1 ELSE 0 END AS IS_BLIND FROM PRODUCT P JOIN MEMBER M ON P.MEMBER_ID = M.MEMBER_ID LEFT JOIN MEMBER_DETAIL MD ON M.MEMBER_ID = MD.MEMBER_ID WHERE P.IS_DELETED = 0
AND P.UNIV_ID = #{univId}
AND (P.PRODUCT_NAME LIKE '%' || #{keyword} || '%' OR P.DESCRIPTION LIKE '%' || #{keyword} || '%')
AND P.CATEGORY = #{category}
AND P.PRODUCT_STATUS = #{productStatus}
AND P.PRODUCT_STATUS != 'DONE'
AND ( (SELECT COUNT(*) FROM PRODUCT_REPORT PR WHERE PR.PRODUCT_ID = P.PRODUCT_ID) < 5 OR P.MEMBER_ID = #{viewerMemberId} ) ORDER BY P.CREATED_AT DESC OFFSET #{page} * #{size} ROWS FETCH NEXT #{size} ROWS ONLY

SELECT COUNT(*)
FROM PRODUCT P
WHERE P.IS_DELETED = 0

    AND P.UNIV_ID = #{univId}


    AND (P.PRODUCT_NAME LIKE '%' || #{keyword} || '%'
      OR P.DESCRIPTION  LIKE '%' || #{keyword} || '%')


    AND P.CATEGORY = #{category}


    AND P.PRODUCT_STATUS = #{productStatus}


    AND P.PRODUCT_STATUS != 'DONE'

AND (
    (SELECT COUNT(*) FROM PRODUCT_REPORT PR WHERE PR.PRODUCT_ID = P.PRODUCT_ID) < 5
    OR P.MEMBER_ID = #{viewerMemberId}
)

