mapper.select:
SELECT P.PRODUCT_ID, P.MEMBER_ID, P.UNIV_ID, P.PRODUCT_NAME, P.PRICE, P.VIEW_COUNT, P.IS_DELETED, P.CREATED_AT, P.UPDATED_AT, P.PRODUCT_STATUS, P.PLACE, P.CATEGORY, M.MEMBER_NAME AS SELLER_NAME, MD.COMMUNITY_NICKNAME AS SELLER_NICKNAME, (SELECT COUNT(*) FROM PRODUCT_LIKE PL2 WHERE PL2.PRODUCT_ID = P.PRODUCT_ID) AS LIKE_COUNT, (SELECT COUNT(*) FROM TRADE_CHAT_ROOM TC WHERE TC.PRODUCT_ID = P.PRODUCT_ID) AS CHAT_COUNT, (SELECT COUNT(*) FROM PRODUCT_REPORT PR WHERE PR.PRODUCT_ID = P.PRODUCT_ID) AS REPORT_COUNT, 0 AS HAS_UNREAD_TRADE_CHAT, CASE WHEN (SELECT COUNT(*) FROM PRODUCT_REPORT PR WHERE PR.PRODUCT_ID = P.PRODUCT_ID) >= 5 THEN 1 ELSE 0 END AS IS_BLIND FROM PRODUCT_LIKE PL JOIN PRODUCT P ON PL.PRODUCT_ID = P.PRODUCT_ID JOIN MEMBER M ON P.MEMBER_ID = M.MEMBER_ID LEFT JOIN MEMBER_DETAIL MD ON M.MEMBER_ID = MD.MEMBER_ID WHERE PL.MEMBER_ID = #{memberId} AND P.IS_DELETED = 0
AND P.UNIV_ID = #{univId}
AND (SELECT COUNT(*) FROM PRODUCT_REPORT PR WHERE PR.PRODUCT_ID = P.PRODUCT_ID) < 5 ORDER BY PL.PRESSED_AT DESC

mapper.update:
UPDATE TRADE_CHAT_MESSAGE
SET IS_READ = 1
WHERE ROOM_ID = #{roomId}
  AND SENDER_ID != #{memberId}
  AND IS_READ = 0

UPDATE TRADE_CHAT_ROOM
SET NEGOTIATED_PRICE = #{negotiatedPrice}
WHERE ROOM_ID = #{roomId}

UPDATE TRADE_CHAT_ROOM
SET STATUS = #{status}
WHERE ROOM_ID = #{roomId}

UPDATE TRADE_CHAT_ROOM
SET STATUS = #{status}
WHERE PRODUCT_ID = #{productId}
  AND STATUS = 'ACTIVE'

UPDATE TRADE_CHAT_ROOM
SET STATUS = #{status}
WHERE PRODUCT_ID = #{productId}
  AND ROOM_ID != #{excludeRoomId}
  AND STATUS = 'ACTIVE'
